# Problem (Algebra, Level 5):

The equation $y = \dfrac{x + A}{Bx + C}$, where $A$, $B$, and $C$ are integers, is shown below. What is $A + B + C$?

[asy]
import graph; size(8.14cm); real lsf=0.5; pen dps=linewidth(0.7)+fontsize(10); defaultpen(dps); pen ds=black; real xmin=-3.52,xmax=6.62,ymin=-4.28,ymax=4.32;

pen cqcqcq=rgb(0.75,0.75,0.75);

/*grid*/ pen gs=linewidth(0.7)+cqcqcq+linetype("2 2"); real gx=1,gy=1;
for(real i=ceil(xmin/gx)*gx;i<=floor(xmax/gx)*gx;i+=gx) draw((i,ymin)--(i,ymax),gs); for(real i=ceil(ymin/gy)*gy;i<=floor(ymax/gy)*gy;i+=gy) draw((xmin,i)--(xmax,ymax),gs);

Label laxis;
